{
  "justification": "Cost-of-living and the wider economy dominate salience, with immigration also very high; attitudes are centrist on left–right and redistribution but notably more authoritarian and slightly below-mid on EU integration. This pattern points to strong Care, Authority and Proportionality pulls, meaningful Loyalty, and smaller but present Equality and Sanctity (via environment/naturalness).",
  "foundations": [
    {
      "foundation": "care",
      "basis": "High salience of living costs (19.7%) and health (7.0%), plus some concern for poverty (1.3%) and inequality (1.1%).",
      "weight": 0.2
    },
    {
      "foundation": "loyalty",
      "basis": "Immigration salience (17.0%) and below-mid EU integration (4.73), with defence (1.3%) and war (2.0%) indicating national-cohesion concerns.",
      "weight": 0.16
    },
    {
      "foundation": "authority",
      "basis": "Derived authority-liberty score is 6.2 (more authoritarian), with crime (2.4%) and immigration control salient.",
      "weight": 0.22
    },
    {
      "foundation": "sanctity",
      "basis": "Environment salience (6.1%) and a small ‘morals’ category (0.3%) invoke purity/naturalness themes.",
      "weight": 0.1
    },
    {
      "foundation": "equality",
      "basis": "Redistribution placement 4.68 near the midpoint and modest salience for inequality (1.1%) and poverty (1.3%).",
      "weight": 0.12
    },
    {
      "foundation": "proportionality",
      "basis": "Economy-general (13.7%) and taxation (0.5%) salience with centrist left-right (4.74) reflect merit/performance concerns.",
      "weight": 0.2
    }
  ]
}

{
  "justification": "Across both surveys, issue salience clusters around NHS/health, the economy and prices, and immigration; BES also shows slightly authoritarian social attitudes (mean 6.2), near‑centre economic redistribution (4.68), and modest Euroscepticism (EU 4.73). Given salience without direction and immigration’s bidirectional pull, we weight Care and Authority highest, spread moderate weight to Loyalty and Equality, reserve some for Proportionality via economy/tax themes, and keep Sanctity relatively low.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "NHS/Healthcare 41%, Ageing population/Social care 6%, Poverty/Inequality 12%, Environment 9% (harm concerns).",
      "weight": 0.24
    },
    {
      "foundation": "authority",
      "basis": "Authority–liberty mean 6.2 (more authoritarian), Crime/Law and order 10%, Defence/Foreign affairs 12%.",
      "weight": 0.21
    },
    {
      "foundation": "loyalty",
      "basis": "Immigration 30% (Ipsos)/17% (BES), Defence/Foreign affairs 12%, Europe/Brexit 5%, EU integration mean 4.73 (slightly sceptical).",
      "weight": 0.17
    },
    {
      "foundation": "equality",
      "basis": "Poverty/Inequality 12%, Low pay/Minimum wage 5%, Pensions/Benefits 4%, redistribution position 4.68 (slightly pro‑redistribution).",
      "weight": 0.16
    },
    {
      "foundation": "proportionality",
      "basis": "Economy 33%, Inflation/Prices 29% (Living costs 19.7%), Taxation 7%, Unemployment/Industry 6%.",
      "weight": 0.14
    },
    {
      "foundation": "sanctity",
      "basis": "Pollution/Environment/Climate change 9%, Morality/Individual behaviour 2%, Drug abuse 1%.",
      "weight": 0.08
    }
  ]
}

{
  "justification": "Most salience is concentrated on issues that are orthogonal to GAL–TAN (NHS, economy, prices), so only a limited share of the data informs this axis. Among the clearly GAL–TAN-relevant items, concerns tied to order, sovereignty and national identity (immigration 30%, crime 10%, defence/terrorism 12%, EU 5%) outweigh explicitly liberal–multicultural or green priorities (environment 9%, race relations 2%), so I assign a modest TAN tilt.",
  "poles": [
    {
      "pole": "gal",
      "basis": "Pollution/Environment/Climate change; Race relations",
      "weight": 0.4
    },
    {
      "pole": "tan",
      "basis": "Immigration/Immigrants; Crime/Law and order/Violence/Vandalism; Defence/Foreign affairs/International terrorism; Common Market/Brexit/EU/Europe; Morality/Individual behaviour/Lifestyle; Population levels/Overpopulation",
      "weight": 0.6
    }
  ]
}

{
  "justification": "With a derived authority–liberty mean of 6.2 (higher=authoritarian) and EU integration at 4.73, the electorate shows a moderate TAN lean toward order, sovereignty, and national identity, reinforced by high immigration salience (17%). Some GAL pull remains, reflected in meaningful environmental salience (6.1%) and only mild, not hard, Euroscepticism.",
  "poles": [
    {
      "pole": "tan",
      "basis": "Slot 6 authority–liberty=6.2 (authoritarian); Slot 7 EU integration=4.73; Slot 3 immigration salience=17%.",
      "weight": 0.62
    },
    {
      "pole": "gal",
      "basis": "Slot 3 environment salience=6.1%; Slot 7 EU integration near midpoint (4.73) indicating only mild Euroscepticism.",
      "weight": 0.38
    }
  ]
}

{
  "justification": "The BES authority–liberty scale mean of 6.2/10 indicates a noticeable tilt toward authoritarian values, and the European integration placement at 4.73/10 suggests mild Euroscepticism—both TAN-consistent. Because the Ipsos and BES salience measures do not encode direction, they mainly show contested domains rather than push the position, so I weight TAN over GAL but retain a sizable GAL share.",
  "poles": [
    {
      "pole": "tan",
      "basis": "BES authority–liberty mean 6.2 (authoritarian-leaning) and EU integration mean 4.73 (mild Euroscepticism).",
      "weight": 0.6
    },
    {
      "pole": "gal",
      "basis": "EU and authority–liberty means are near midpoints rather than TAN extremes, and the environment is salient (Ipsos 9%; BES 6.1%).",
      "weight": 0.4
    }
  ]
}

